template <bool Purposed, class Result>
PlatformRequest<Purposed, Result>& PlatformRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

template <bool Purposed, class Result>
SpecialistRequest<Purposed, Result>&
SpecialistRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

template <bool Purposed, class Result>
SchoolRequest<Purposed, Result>& SchoolRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    enhanceChild(AcademyRequest<false>(query_.template childQuery<Academy>())
                     .unlimited()
                     .selectSelfFields()
                     .enhanceChildrenIfNeeded());
    return *this;
}

template <bool Purposed, class Result>
AcademyRequest<Purposed, Result>& AcademyRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    enhanceChild(ResearchAcademyRequest<false>(query_.template childQuery<ResearchAcademy>())
                     .unlimited()
                     .selectSelfFields()
                     .enhanceChildrenIfNeeded());
    return *this;
}

template <bool Purposed, class Result>
ResearchAcademyRequest<Purposed, Result>&
ResearchAcademyRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

template <bool Purposed, class Result>
EnrollmentRequest<Purposed, Result>&
EnrollmentRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

class query_factory {
    ContextBinding binding_;

public:
    explicit query_factory(UserContext& user_context) : binding_(user_context) {}

    PlatformRequest<false> platformsMinimal() const {
        return PlatformRequest<false>(binding_.get(), true);
    }

    PlatformRequest<false> platforms() const {
        return PlatformRequest<false>(binding_.get());
    }

    PlatformRequest<false> platformsWithChildren() const {
        return PlatformRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    SpecialistRequest<false> specialistsMinimal() const {
        return SpecialistRequest<false>(binding_.get(), true);
    }

    SpecialistRequest<false> specialists() const {
        return SpecialistRequest<false>(binding_.get());
    }

    SpecialistRequest<false> specialistsWithChildren() const {
        return SpecialistRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    SchoolRequest<false> schoolsMinimal() const {
        return SchoolRequest<false>(binding_.get(), true);
    }

    SchoolRequest<false> schools() const {
        return SchoolRequest<false>(binding_.get());
    }

    SchoolRequest<false> schoolsWithChildren() const {
        return SchoolRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    AcademyRequest<false> academiesMinimal() const {
        return AcademyRequest<false>(binding_.get(), true);
    }

    AcademyRequest<false> academies() const {
        return AcademyRequest<false>(binding_.get());
    }

    AcademyRequest<false> academiesWithChildren() const {
        return AcademyRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    ResearchAcademyRequest<false> researchAcademiesMinimal() const {
        return ResearchAcademyRequest<false>(binding_.get(), true);
    }

    ResearchAcademyRequest<false> researchAcademies() const {
        return ResearchAcademyRequest<false>(binding_.get());
    }

    ResearchAcademyRequest<false> researchAcademiesWithChildren() const {
        return ResearchAcademyRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }

    EnrollmentRequest<false> enrollmentsMinimal() const {
        return EnrollmentRequest<false>(binding_.get(), true);
    }

    EnrollmentRequest<false> enrollments() const {
        return EnrollmentRequest<false>(binding_.get());
    }

    EnrollmentRequest<false> enrollmentsWithChildren() const {
        return EnrollmentRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }
};
